<?php require __DIR__.'/../includes/app.php'; need('System Administrator','Business Manager','Vehicle Inspector/Maintenance Staff');
if($_SERVER['REQUEST_METHOD']==='POST'){chk();$p=$_POST;
 if($p['act']==='new'){q('INSERT INTO maintenance_records(maintenance_number,vehicle_id,reported_by,maintenance_type,title,description,service_provider,start_date,expected_completion_date,cost,next_service_date,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[code('MNT'),$p['vehicle_id'],user()['id'],$p['maintenance_type'],$p['title'],$p['description'],$p['service_provider'],$p['start_date'],$p['expected_completion_date']?:null,$p['cost']?:0,$p['next_service_date']?:null,$p['status']]);
  if(in_array($p['status'],['scheduled','in_progress']))q("UPDATE vehicles SET status='maintenance' WHERE vehicle_id=? AND status='available'",[$p['vehicle_id']]);flash('Maintenance record added.');}
 else{$m=q('SELECT * FROM maintenance_records WHERE maintenance_id=?',[$p['id']])->fetch();q('UPDATE maintenance_records SET status=?,cost=?,completed_date=IF(?="completed",CURDATE(),completed_date) WHERE maintenance_id=?',[$p['status'],$p['cost']?:0,$p['status'],$p['id']]);
  if(in_array($p['status'],['completed','cancelled'])&&!q("SELECT 1 FROM maintenance_records WHERE vehicle_id=? AND status IN('scheduled','in_progress')",[$m['vehicle_id']])->fetch())q("UPDATE vehicles SET status='available' WHERE vehicle_id=? AND status='maintenance'",[$m['vehicle_id']]);flash('Record updated.');}
 audit('maintenance','maintenance',$p['id']??'');header('Location: maintenance.php');exit;}
head('Maintenance');$vs=q("SELECT vehicle_id,CONCAT(make,' ',model,' - ',registration_no) n FROM vehicles")->fetchAll(PDO::FETCH_KEY_PAIR);$ty=['routine_service','repair','inspection','tyres','oil_change','bodywork','other'];$st=['scheduled','in_progress','completed','cancelled'];?>
